  ('tunis-tunisia', '04A', 'Tunis, Carthage & Sidi Bou Saïd', 'Tunisia', 'Carthage, the medina, and blue-and-white Sidi Bou Saïd over', 'live', 'verified', 'kyoto', 'The Maghreb', '{"culture","culinary","ultra"}', '{}', '{"essential","comfort","luxury","ultra"}', null, 'anchor', '{"key_facts":["Two thousand years on one coast - the UNESCO Medina of Tunis (1979, 700+ monuments), ancient Carthage (UNESCO Punic + Roman ruins), and blue-and-white Sidi Bou Said over the Gulf","The Bardo Museum holds the world''s largest collection of Roman mosaics","Heritage dar stays - restored mansions like Dar Said (Sidi Bou Said) and Dar El Jeld (Medina)","Do-Not-Travel areas are the western Chaambi mountains + Libya/Algeria border strips, far from the coast","Sold via Tunisia DMCs + heritage dars ~10-16%; site/museum tickets non-commissionable pass-through","Best season Mar-May & Sep-Nov; base here then head to the Sahara or Djerba"],"safety":{"emergency":"197 police / 190 ambulance (SAMU) / 198 civil protection","hospital":"Tunis private clinics (Clinique El Amen) + public hospitals; carry travel-medical + evac insurance","activity_note":"Do-Not-Travel areas (Chaambi Mountains, Libya/Algeria 16km border strips except Tabarka/Ain Draham, Mount Orbata, desert south of Remada) are far from the coast. Standard medina street-smarts; agreed prices, a guide the first time.","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/tunisia","read":"2026-08-20T14:48:51Z","page_updated":"2026-07-24T17:07:53+01:00","source_country":"tunisia","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The Chaambi Mountains National Park","lvl":4,"posture":"all","note":"Cross-border terrorist activity and operations by the Tunisian security forces."},{"name":"The designated military operations zones of Mount Salloum, Mount Sammamma and Mount Mghila","lvl":4,"posture":"all"},{"name":"The militarised zone south of the towns of El Borma and Dhehiba","lvl":4,"posture":"all","note":"Cross-border terrorist activity and fighting in Libya."},{"name":"Within 20km of the rest of the Tunisia-Libya border area north of Dhehiba","lvl":4,"posture":"all"},{"name":"The town of Ben Guerdane and immediate surrounding area","lvl":4,"posture":"all"},{"name":"Areas north and west of the town of Ghardimaou in Jendouba Governorate, including El Feidja National Park","lvl":3,"posture":"all-but-essential"},{"name":"Within 20km of the Tunisia-Algeria border in El Kef and Jendouba governorates, south of the town of Jendouba","lvl":3,"posture":"all-but-essential","note":"Including the archaeological site of Chemtou."},{"name":"Kasserine Governorate, including the town of Sbeitla","lvl":3,"posture":"all-but-essential"},{"name":"Within 10km of the rest of the Tunisia-Algeria border south of Kasserine Governorate","lvl":3,"posture":"all-but-essential"},{"name":"Within 10km of Mount Mghila","lvl":3,"posture":"all-but-essential"},{"name":"Mount Orbata","lvl":3,"posture":"all-but-essential"},{"name":"Within 75km of the Tunisia-Libya border","lvl":3,"posture":"all-but-essential","except":["Zarzis","the C118 road","all areas in Medenine Governorate north of the C118 road"],"note":"Including Remada and El Borma."}]},"timing":{"peak":"Mar-May & Sep-Nov (mild); European summer + Christmas/NY secondary","shoulder":"Feb + Dec","green":"Jun-Aug (hot, coastal-crowded)","booking_lead":"dars + Tunisia loops 2-4 mo for spring/autumn","off_season_specials":"summer coastal value; pair with the Sahara + Djerba","event_peaks":"Mar-May + Sep-Nov; European holidays","fire_date":"sell spring/autumn culture loops 3-5 mo out; lead FR + EN; pair with Sahara + Djerba"},"jewels":[{"name":"Carthage + the Bardo mosaics","si_tag":"culture","status":"live","tier":"comfort","price_band":"within the tour","timing":"Mar-May & Sep-Nov","draw_rank":1,"when_source":"derived from destination t