  ('maasai-mara-kenya', '05A', 'Maasai Mara National Reserve', 'Kenya', 'The big-cat capital of the world', 'live', 'verified', 'safariGiraffe', 'Kenya — Maasai Mara', '{"safari","ultra","romance","adventure","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["The densest big-cat population in Africa (~850-900 lions across reserve + conservancies, plus leopard + cheetah); the Great Migration''s Kenyan climax - Mara River crossings Jul-Oct (peak Aug-Sep) + return Oct-Nov","Reserve vs conservancies: the community/private conservancies bordering the reserve = FAR fewer vehicles + reserve-banned activities (walking safaris, off-road driving, night drives) - the exclusive/ultra choice","Best Jul-Oct for the migration, Jan-Mar for big cats; long rains Apr-May cheapest; book 6-12 mo ahead for peak","Reserve entry $200/pp/day (2026 peak); mid-range 4-day ~$1,400-2,500/pp (incl flight); luxury 4-night peak $3,450-7,800/pp; dawn balloon ~$450-500/pp","sold via Kenya safari DMCs at a favourable 15-25% - IATAN/host-gated, CLIA has NO Africa representation","KES (~129/USD) + M-Pesa everywhere but safari quoted in USD; eTA required (replaced visas 2024); malaria prophylaxis advised; YF only if arriving from a risk country; AMREF Flying Doctors for evac"],"safety":{"emergency":"999 / 112 / 911 (reliable in cities, limited in the Mara); Kenya Red Cross ambulance 1199; AMREF Flying Doctors for bush evac","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d, evac to Nairobi) + travel-medical insurance; nearest referral Nairobi","malaria":"prophylaxis advised (CDC - the Mara qualifies, chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory only if arriving from a risk country (cert valid 10d post-injection); CDC recommends for most","activity_note":"Dangerous game at close range - stay in the vehicle, follow the guide. Crossings: 3,000+ crocodiles + panicked herds - designated vantage points only, never approach on foot. Conservancy walking with armed guide only. Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/kenya","read":"2026-08-20T14:53:50Z","page_updated":"2026-06-24T12:48:44+01:00","source_country":"kenya","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Mandera, Wajir and Garissa counties","lvl":4,"note":"The Somalia border counties."},{"name":"Lamu County","lvl":4},{"name":"Tana River","lvl":4},{"name":"Kilifi north of Malindi","lvl":4},{"name":"The northern border areas","lvl":4},{"name":"Eastleigh, Nairobi","lvl":3},{"name":"Kibera, Nairobi","lvl":3}]},"timing":{"peak":"Jul-Oct (Great Migration + Mara River crossings, Aug-Sep drama); secondary Jan-Mar (green + big cats)","shoulder":"Jun (herds arriving) + Nov (short rains, return crossings)","green":"Apr-May (long rains - lush, quiet, cheapest)","booking_lead":"6-12 mo for Jul-Oct peak (reserve + conservancy camps sell out); mid-range 3-6 mo; green 1-3 mo","off_season_specials":"Apr-May green-season value + Jan-Mar big-cat season (no migration crush); conservancy walking/night-drive packages year-round","event_peaks":"Jul-Oct crossing crush + Christmas/NY + Easter; N-Hemisphere summer","fire_date":"Jul-Oct crossings 9-12 mo out (by prior Oct-Dec); Jan-Mar big-cat season by prior Sep-Nov; green-season value by prior Nov-Dec"},"jewels":[{"name":"The Mara River crossings","si_tag":"safari","status":"live","tier":"premier","price_band":"~$1,000-2,500/pp/day","timing":"Jul-Oct; book 9-12 mo","draw_rank":1,"hook":"3,000+ crocodiles + panicked herds — keep to designated vantage points, never approach the bank on foot","si":"safari","blurb":"3,000+ crocodiles + panicked herds — keep to designated vantage points, never approach the bank on foot","when":"Jul-Oct; book 9-12 mo","commission":"safari DMC 15-25%","wells":["move"],"wells_basis":"p